// ---------------------------------------

type AnalyticsEvent = 'checkout_started' | 'order_placed' | 'payment_failed';

// "Library" config interface (pretend it lives in a package you cannot edit).
interface CheckoutConfig {
  currency: string;
}

// The analytics snippet, as far as we use it (checked against snippet v3).
declare var cartwheelAnalytics: {
  readonly sent: readonly string[];
  track(event: AnalyticsEvent, props?: Record<string, string | number>): void;
};

// ES2023 method, present in every current browser but missing from the ES2022 lib.
interface Array<T> {
  findLast(predicate: (value: T, index: number, array: T[]) => unknown): T | undefined;
}

// Merges with the library's CheckoutConfig.
interface CheckoutConfig {
  giftWrap: boolean;
}

type Order = { id: number; status: 'processing' | 'shipped' | 'delivered'; totalCents: number };

const orders: Order[] = [
  { id: 1041, status: 'shipped', totalCents: 4500 },
  { id: 1042, status: 'shipped', totalCents: 18900 },
  { id: 1043, status: 'processing', totalCents: 1200 },
];

function latestShipped(list: Order[]): Order | undefined {
  return list.findLast((o) => o.status === 'shipped');
}

function placeOrder(order: Order): void {
  cartwheelAnalytics.track('order_placed', { orderId: order.id, totalCents: order.totalCents });
}

const config: CheckoutConfig = { currency: 'EGP', giftWrap: true };

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<keyof CheckoutConfig, 'currency' | 'giftWrap'>>;
type T2 = Expect<Equal<ReturnType<typeof latestShipped>, Order | undefined>>;

function typeTests() {
  // @ts-expect-error: not a known analytics event
  cartwheelAnalytics.track('ordr_placed');
  // @ts-expect-error: property values must be strings or numbers
  cartwheelAnalytics.track('checkout_started', { express: true });
}

placeOrder(latestShipped(orders)!);
console.log(latestShipped(orders)?.id, cartwheelAnalytics.sent, config);
